    71→  /**
    72→   * Transforms an input row, or returns null if the row should be filtered out.
    73→   *
    74→   * @param row the input row
    75→   */
    76→  @Nullable
    77→  public InputRow transform(@Nullable final InputRow row)
    78→  {
    79→    if (row == null) {
    80→      return null;
    81→    }
    82→
    83→    final InputRow transformedRow;
    84→
    85→    if (transforms.isEmpty()) {
    86→      transformedRow = row;
    87→    } else {
    88→      transformedRow = new TransformedInputRow(row, transforms);
    89→    }
    90→
    91→    if (valueMatcher != null) {
    92→      rowSupplierForValueMatcher.set(transformedRow);
    93→      if (!valueMatcher.matches()) {
    94→        return null;
    95→      }
    96→    }
    97→
    98→    return transformedRow;
    99→  }
